const colors={Primary:'#168078',Secondary:'#d39a31',Tertiary:'#6654a4',Unclassified:'#80909c'};
const labels={photo:'Phototherapy',cpap:'CPAP respiratory support',power:'Electricity',solar:'Solar backup',water:'Running water',surgery:'Paediatric surgery (mission)',neonatal:'Tertiary neonatal care'};
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let facilities=[],visible=[],selected=null,level='All',markers=new Map();
const map=L.map('map',{zoomControl:false,zoomSnap:0.25}).setView([13.48,-15.35],8);L.control.zoom({position:'topright'}).addTo(map);L.control.scale({imperial:false,position:'bottomright'}).addTo(map);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',subdomains:'abcd',maxZoom:19}).addTo(map);
const group=L.layerGroup().addTo(map);
function matching(f){return(level==='All'||f.level===level)&&($('coverage').value!=='assessed'||f.assessed)&&(! $('search').value.trim()||`${f.name} ${f.aliases} ${f.region}`.toLowerCase().includes($('search').value.trim().toLowerCase()))&&(!$('resource').value||(f.resources[$('resource').value]||'unknown')===$('status').value)}
function render(){visible=facilities.filter(matching);group.clearLayers();markers.clear();$('count').textContent=`${visible.length} facilit${visible.length===1?'y':'ies'}`;$('mapstats').textContent=`${visible.length} shown · ${visible.filter(f=>f.assessed).length} with neonatal assessment`;
$('results').innerHTML=visible.length?visible.map(f=>`<button class="facility${selected===f.id?' selected':''}" data-id="${esc(f.id)}"><strong>${esc(f.name)}</strong><small><span class="dot" style="background:${colors[f.level]}"></span>${esc(f.level)} · ${esc(f.region)}${f.assessed?'<span class="assessed">ASSESSED</span>':''}</small></button>`).join(''):'<div class="empty">No facilities match these filters. Try another provision status or reset the filters.</div>';
visible.forEach(f=>{let m=L.circleMarker([f.lat,f.lng],{radius:f.assessed?8:5,color:'white',weight:1.8,fillColor:colors[f.level],fillOpacity:.92}).addTo(group).bindTooltip(esc(f.name),{direction:'top'}).on('click',()=>select(f.id));markers.set(f.id,m)});
if(selected&&!visible.some(f=>f.id===selected))closeDetail();else if(selected)highlight();
}
function highlight(){markers.forEach((m,id)=>m.setStyle({radius:id===selected?12:facilities.find(f=>f.id===id).assessed?8:5,weight:id===selected?3:1.8,color:id===selected?'#193e42':'white'}))}
function select(id){let f=facilities.find(f=>f.id===id);selected=id;map.setView([f.lat,f.lng],Math.max(map.getZoom(),11));$('detail').hidden=false;$('detail').innerHTML=`<button class="close" id="closeDetail" aria-label="Close facility details">×</button><div class="eyebrow">FACILITY PROFILE</div><h2>${esc(f.name)}</h2><span class="badge">${esc(f.level)} care</span><p>${esc(f.region)} · ${esc(f.ownership)}<br>${esc(f.type)}<br>${esc(f.levelBasis)}</p><div class="eyebrow">REPORTED SERVICES & RESOURCES</div>${Object.entries(labels).map(([k,label])=>{const v=f.resources[k]||'unknown';return `<div class="resourceRow"><span>${label}</span><strong class="${v}">${v==='yes'?(k==='photo'?'Some · insufficient':'Available'):v==='no'?'Unavailable':'Not documented'}</strong></div>`}).join('')}<p>${f.assessed?'Assessment: PATG workshop, 12–13 November 2025. Electricity/water may be intermittent despite “Yes” responses. CPAP: structured table used; conflicting unattributed workshop comments remain unresolved.':'No facility-level neonatal resource assessment in the supplied reports.'}${f.resources.surgery?' Paediatric surgery: November 2025 HF mission activity; ongoing availability unconfirmed.':''}</p><p><b>${f.approx?'Approximate locality position':'Source coordinates'}</b><br>${f.lat.toFixed(5)}, ${f.lng.toFixed(5)}<br>${esc(f.locationSource)}</p><a href="${esc(f.locationUrl)}" target="_blank" rel="noopener">View location source ↗</a><p>Recorded name: ${esc(f.aliases)}</p>`;$('closeDetail').onclick=closeDetail;document.querySelectorAll('.facility').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));highlight()}
function closeDetail(){selected=null;$('detail').hidden=true;document.querySelectorAll('.facility').forEach(b=>b.classList.remove('selected'));highlight()}
function fit(){if(visible.length)map.fitBounds(L.latLngBounds(visible.map(f=>[f.lat,f.lng])),{padding:[35,100],maxZoom:13})}
$('results').onclick=e=>{let b=e.target.closest('[data-id]');if(b)select(b.dataset.id)};
['search','coverage','status'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('resource').onchange=()=>{$('status').disabled=!$('resource').value;render()};
function drawLevels(){$('levels').innerHTML=['All',...Object.keys(colors)].map(l=>`<button data-level="${l}" aria-pressed="${l===level}" class="${l===level?'active':''}">${l}</button>`).join('')}
$('levels').onclick=e=>{if(e.target.dataset.level){level=e.target.dataset.level;drawLevels();render()}};
$('reset').onclick=()=>{level='All';$('search').value='';$('coverage').value='all';$('resource').value='';$('status').value='yes';$('status').disabled=true;drawLevels();render();fit()};$('fit').onclick=fit;
$('sourcesButton').onclick=()=>$('sources').showModal();$('closeSources').onclick=()=>$('sources').close();$('sources').onclick=e=>{if(e.target===$('sources')){const r=$('sources').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('sources').close()}};
$('export').onclick=()=>{const headers=['Facility','Level','Facility type','Region','Ownership','Latitude','Longitude','Approximate location','Assessment Nov 2025',...Object.values(labels),'Location source','Level basis'];const quote=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const csv=[headers,...visible.map(f=>[f.name,f.level,f.type,f.region,f.ownership,f.lat,f.lng,f.approx,f.assessed,...Object.keys(labels).map(k=>f.resources[k]||'unknown'),f.locationSource,f.levelBasis])].map(r=>r.map(quote).join(',')).join('\r\n');let u=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='gambia-health-facilities.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
async function init(){try{const r=await fetch('facilities.json');if(!r.ok)throw Error('Facility data failed to load');facilities=await r.json();$('coverageNote').textContent=`${facilities.length} facilities: 101 historical public-sector database records plus Ahmadiyya and Njau from the supplied assessment. All 15 assessed facilities are included. Private, new, renamed, closed and unmapped facilities may be missing. Only 15 have structured resource data; other services remain undocumented. Njau is placed at an approximate village location. Care levels describe the general health system, not neonatal intensive-care capability.`;drawLevels();render();fit();const b=await fetch('gambia-boundary.json');if(b.ok)L.geoJSON(await b.json(),{interactive:false,style:{color:'#408479',weight:1.6,fillColor:'#70ad8b',fillOpacity:.06}}).addTo(map).bringToBack()}catch(e){$('results').textContent='Unable to load facility data. Please reload the page.';console.error(e)}}init();
